// ===== MONTAR BUSCA =====
// Define o que será buscado no Gmail. Dois caminhos chegam aqui:
//  - Schedule Trigger (diário): últimos 3 dias, só emails ainda sem o rótulo "Vagas-processado"
//  - Webhook (backfill manual): usa ?dias=60  ou  ?inicio=2026/08/01&fim=2026/10/16

// ====== CONFIGURAÇÃO ======
const DIAS_DIARIO = 3;
const DIAS_BACKFILL_PADRAO = 60;
const ROTULO_PROCESSADO = 'Vagas-processado';
const REMETENTES = [
  'jobalerts-noreply@linkedin.com',
  'noreply@glassdoor.com',
  'donotreply@jobalert.indeed.com',
  'donotreply@match.indeed.com'
];
// ==========================

const entrada = $input.first().json || {};
const query = entrada.query || {};            // vem do Webhook (?dias=..&inicio=..&fim=..)
const veioDoWebhook = !!(entrada.query || entrada.headers);

let periodo = `newer_than:${DIAS_DIARIO}d`;
let modo = 'diario';
if (veioDoWebhook) {
  modo = 'backfill';
  const ok = (d) => /^\d{4}\/\d{2}\/\d{2}$/.test(d || '');
  if (ok(query.inicio) || ok(query.fim)) {
    periodo = [ok(query.inicio) ? `after:${query.inicio}` : '', ok(query.fim) ? `before:${query.fim}` : ''].filter(Boolean).join(' ');
  } else {
    const dias = Math.min(Math.max(parseInt(query.dias, 10) || DIAS_BACKFILL_PADRAO, 1), 400);
    periodo = `newer_than:${dias}d`;
  }
}

const q = `from:(${REMETENTES.join(' OR ')}) ${periodo} -label:${ROTULO_PROCESSADO}`;
return [{ json: { q, modo, periodo } }];

// ===== EXTRAIR E ENFILEIRAR =====
// Lê os emails de alerta, extrai as vagas, tira repetidas, faz a triagem barata por título,
// guarda o excedente numa fila (memória do workflow) e entrega só as vagas do dia para a IA.

// ====== CONFIGURAÇÃO ======
const LIMITE_IA_POR_RODADA = 50;  // vagas que vão para a IA por execução (Groq grátis)
const LIMITE_TESTE = 5;           // em execução manual (teste) só processa esta quantidade
const MAX_VISTOS = 6000;          // quantos IDs de vagas já vistas ficam guardados
const MAX_FILA = 800;             // tamanho máximo da fila de espera
const DIAS_VALIDADE = 45;         // vaga na fila há mais tempo que isso é descartada
const SNIPPET_MAX = 400;          // caracteres do trecho de descrição vindo do email

// ====== UTILIDADES ======
const norm = (s) => (s || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const hash = (s) => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return (h >>> 0).toString(36); };
const decode = (s) => (s || '').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const linhas = (t) => (t || '').split(/\r?\n/).map(s => s.replace(/[​-‏⁠﻿͏]/g, '').trim());

function htmlParaMd(html) {
  return decode((html || '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<a\b[^>]*?href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (m, h, t) => '[' + t.replace(/<[^>]+>/g, '|') + '](' + h + ')')
    .replace(/<br\s*\/?>|<\/(p|div|tr|li|h\d|table)>/gi, '\n')
    .replace(/<[^>]+>/g, ' '));
}
function htmlParaTexto(html) {
  return decode((html || '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<a\b[^>]*?href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (m, h, t) => '\n' + t.replace(/<[^>]+>/g, ' ') + '\nURL: ' + h + '\n')
    .replace(/<br\s*\/?>|<\/(p|div|tr|li|h\d|table|td)>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
    .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n\n');
}

// "R$ 3.745 por mês" -> {min,max,texto} em R$/mês
function lerSalario(txt) {
  if (!txt) return null;
  const t = txt.replace(/ /g, ' ');
  const nums = [...t.matchAll(/R\$\s*([\d]{1,3}(?:\.\d{3})*(?:,\d{1,2})?|\d+(?:,\d{1,2})?)/g)]
    .map(m => parseFloat(m[1].replace(/\./g, '').replace(',', '.'))).filter(n => !isNaN(n));
  if (!nums.length) return null;
  let mult = 1;
  const n = norm(t);
  if (/por hora|\/ ?hora/.test(n)) mult = 176;
  else if (/por semana|\/ ?semana/.test(n)) mult = 4.33;
  else if (/por dia|\/ ?dia/.test(n)) mult = 22;
  else if (/por ano|\/ ?ano|anual/.test(n)) mult = 1 / 12;
  const v = nums.map(x => Math.round(x * mult));
  const min = Math.min(...v), max = Math.max(...v);
  if (min < 300) return null; // lixo
  return { min, max, texto: t.trim().slice(0, 80) };
}
const lerModalidade = (s) => {
  const n = norm(s);
  if (/remot|home office|trabalho a distancia/.test(n)) return 'remoto';
  if (/hibrid/.test(n)) return 'hibrido';
  if (/presencial/.test(n)) return 'presencial';
  return null;
};
const idadeDias = (s) => {
  const n = norm(s);
  if (/\b(hoje|agora|just posted|today)\b/.test(n)) return 0;
  if (/\bontem\b/.test(n)) return 1;
  const m = n.match(/(\d+)\s*(\+)?\s*(dia|d\b|hora|h\b|semana|mes)/);
  if (!m) return null;
  const v = parseInt(m[1], 10);
  if (/hora|^h/.test(m[3])) return 0;
  if (/semana/.test(m[3])) return v * 7;
  if (/mes/.test(m[3])) return v * 30;
  return v;
};

// ====== PARSERS ======
function parseLinkedIn(txt, ctx) {
  const out = [];
  for (const b of txt.split(/\n-{20,}\n/)) {
    if (!/jobs\/view\/\d+/.test(b)) continue;
    let ls = linhas(b).filter(Boolean);
    const iv = ls.findIndex(l => /jobs\/view\/\d+/.test(l));
    const id = (ls[iv].match(/jobs\/view\/(\d+)/) || [])[1];
    ls = ls.slice(0, iv);
    const ih = ls.map((l, i) => /alerta de vaga|novas vagas correspondem|foi criado|suas preferencias/.test(norm(l)) ? i : -1).filter(i => i >= 0).pop();
    if (ih !== undefined) ls = ls.slice(ih + 1);
    if (!id || ls.length < 3) continue;
    out.push({
      source: 'linkedin', rawId: id, key: 'li:' + id,
      title: ls[0], companyName: ls[1], location: ls[2],
      link: `https://www.linkedin.com/jobs/view/${id}/`,
      fetchUrl: `https://www.linkedin.com/jobs-guest/jobs/api/jobPosting/${id}`,  // endpoint público que devolve a descrição sem login
      description: '', ageDays: null, rating: null,
      modalidade: lerModalidade(ls[2])
    });
  }
  return out;
}

function parseGlassdoor(md, ctx) {
  const out = [];
  const re = /\[([^\]]*?)\]\((https?:\/\/[^)\s]*jobListingId=(\d+)[^)\s]*)\)/g;
  let m;
  while ((m = re.exec(md)) !== null) {
    let tk = m[1].split(/\||\n/).map(s => s.trim()).filter(s => s && s !== '★');
    if (tk.length < 3) continue;
    let company = tk[0], rating = null, i = 1;
    const mr = company.match(/^(.*?)\s+(\d[.,]\d)\s*★?$/);
    if (mr) { company = mr[1]; rating = parseFloat(mr[2].replace(',', '.')); }
    else if (/^\d[.,]\d$/.test(tk[1])) { rating = parseFloat(tk[1].replace(',', '.')); i = 2; }
    const title = tk[i], location = tk[i + 1] || '';
    const resto = tk.slice(i + 2).join(' ');
    out.push({
      source: 'glassdoor', rawId: m[3], key: 'gd:' + m[3],
      title, companyName: company, location,
      link: decode(m[2]),
      description: '', ageDays: idadeDias(resto), rating,
      modalidade: lerModalidade(location)
    });
  }
  return out;
}

function parseIndeedAlerta(txt, ctx) {
  const out = [];
  const ls = linhas(txt);
  let bloco = [];
  const fecha = () => {
    const iu = bloco.findIndex(l => /indeed\.com\/.*[?&]jk=[0-9a-f]+/i.test(l));
    if (iu > 0) {
      const jk = bloco[iu].match(/[?&]jk=([0-9a-f]+)/i)[1];
      let corpo = bloco.slice(0, iu);
      let idade = null;
      if (corpo.length && /^(h[aá]\s+\d|h[aá]\s+mais|hoje|ontem|publicad|\d+\s*(dia|hora)s?)/i.test(corpo[corpo.length - 1])) {
        idade = idadeDias(corpo[corpo.length - 1]); corpo = corpo.slice(0, -1);
      }
      if (corpo.length >= 2) {
        const title = corpo[0];
        const cl = corpo[1];
        const k = cl.lastIndexOf(' - ');
        const companyName = k > 0 ? cl.slice(0, k).trim() : cl;
        const location = k > 0 ? cl.slice(k + 3).trim() : '';
        const extras = corpo.slice(2).filter(l => !/^candidate-se facilmente$|^easily apply$/i.test(l));
        const sal = lerSalario(extras.join(' '));
        const snippet = extras.filter(l => !/R\$/.test(l)).join(' ');
        out.push({
          source: 'indeed', rawId: jk, key: 'in:' + jk,
          title, companyName, location,
          link: `https://br.indeed.com/viewjob?jk=${jk}`,
          description: snippet, ageDays: idade, rating: null,
          salaryMin: sal ? sal.min : null, salaryMax: sal ? sal.max : null, salaryText: sal ? sal.texto : '',
          modalidade: lerModalidade(location)
        });
      }
    }
    bloco = [];
  };
  for (const l of ls) { if (!l) fecha(); else bloco.push(l); }
  fecha();
  return out;
}

function parseIndeedMatch(txt, ctx) {
  const ls = linhas(txt);
  const vm = txt.match(/(?:Ver vaga|Candidatar-se agora):\s*(https?:\/\/\S+)/);
  const link = vm ? vm[1] : '';
  let title = '', company = '', location = '';
  const ms = (ctx.subject || '').match(/^(.*?)\s+na empresa\s+(.*)$/);
  if (ms) { title = ms[1].trim(); company = ms[2].trim(); }
  let i = title ? ls.findIndex(l => l === title) : -1;
  if (i < 0) {
    const f = ls.findIndex(l => /^(Salário|Tipo de vaga|Horário de trabalho|Ambiente de trabalho|Benefícios)\s*:?/i.test(l));
    if (f >= 3) { title = ls[f - 3]; company = ls[f - 2]; location = ls[f - 1]; }
  } else {
    if (!company) company = ls[i + 1] || '';
    location = ls[i + 2] || '';
  }
  if (!title || !link) return [];
  const campo = (rot) => { const l = ls.find(x => new RegExp('^' + rot + '\\s*:', 'i').test(x)); return l ? l.replace(/^[^:]+:\s*/, '') : ''; };
  const sal = lerSalario(campo('Sal[aá]rio'));
  const ib = ls.findIndex(l => /^Benef[ií]cios\s*:/i.test(l));
  const beneficios = [];
  if (ib >= 0) for (let j = ib + 1; j < ls.length && /^[-•*]/.test(ls[j]); j++) beneficios.push(ls[j].replace(/^[-•*]\s*/, ''));
  const amb = campo('Ambiente de trabalho');
  const tipo = campo('Tipo de vaga');
  return [{
    source: 'indeed_match', rawId: hash(norm(title + company + location)),
    key: 'im:' + hash(norm(title + company + location)),
    title, companyName: company, location, link,
    description: [tipo && ('Tipo: ' + tipo), campo('Hor[aá]rio de trabalho') && ('Horário: ' + campo('Hor[aá]rio de trabalho')), amb && ('Ambiente: ' + amb)].filter(Boolean).join('. '),
    ageDays: 0, rating: null,
    salaryMin: sal ? sal.min : null, salaryMax: sal ? sal.max : null, salaryText: sal ? sal.texto : '',
    beneficios, modalidade: lerModalidade(amb) || lerModalidade(location)
  }];
}

// ====== TRIAGEM BARATA POR TÍTULO ======
const SENIORIDADE = ['senior', 'sr', 'pleno', 'pl', 'especialista', 'ii', 'iii', 'iv', 'v', 'lead', 'lider', 'head', 'staff', 'principal', 'arquiteto', 'arquiteta', 'coordenador', 'coordenadora', 'gerente', 'manager', 'director', 'diretor', 'diretora', 'supervisor', 'supervisora', 'executivo', 'executiva'];
const ENG_NAO_TI = ['civil', 'mecanica', 'mecanico', 'eletrica', 'eletrico', 'quimica', 'producao', 'manutencao', 'minas', 'metalurgica', 'ambiental', 'agronomia', 'naval', 'petroleo'];
const FORA_AREA = ['direito', 'juridico', 'medicina', 'enfermagem', 'farmacia', 'odontologia', 'psicologia', 'nutricao', 'veterinaria', 'pedagogia', 'arquitetura', 'fisioterapia', 'biomedicina', 'agronomia', 'laboratorio', 'hse', 'seguranca do trabalho', 'motorista', 'cozinh', 'barbeiro', 'costura'];
const T1 = ['dados', 'data', 'analytics', 'bi', 'power bi', 'python', 'sql', 'ia', 'inteligencia artificial', 'machine learning', 'automacao', 'rpa', 'excel', 'planilha', 'indicadores', 'bi'];
const T2 = ['suporte', 'service desk', 'help desk', 'helpdesk', 'ti', 'tecnologia da informacao', 'infraestrutura', 'sistemas', 'software', 'desenvolvedor', 'desenvolvedora', 'developer', 'programador', 'qa', 'teste', 'testes', 'tester', 'qualidade de software', 'web', 'front end', 'frontend', 'back end', 'backend', 'full stack', 'fullstack', 'informatica', 'redes', 'tecnologia', 'it', 'devops', 'dev'];
const T3 = ['analista', 'atendimento', 'administrativo', 'assistente', 'auxiliar', 'dp', 'departamento pessoal', 'contabil', 'financeiro', 'fiscal', 'logistica', 'estoque', 'comercial', 'pre vendas', 'pre-vendas', 'sdr', 'e-commerce', 'ecommerce', 'operacoes', 'backoffice', 'back office', 'cadastro', 'documentacao', 'arquivista', 'secretaria', 'processos', 'qualidade', 'rh', 'recursos humanos', 'recrutamento', 'marketing', 'vendas', 'atendente', 'recepcionista', 'faturamento', 'cobranca', 'compras', 'suprimentos'];
const ENTRADA = ['estagio', 'estagiario', 'estagiaria', 'trainee', 'junior', 'jr', 'aprendiz', 'assistente', 'auxiliar', 'entrada', 'intern', 'internship', 'jovem talento', 'young talent'];

const temTermo = (t, lista) => lista.some(x => {
  if (x.length <= 4 || x.indexOf(' ') > 0 || x.indexOf('-') > 0) return new RegExp('(^|[^a-z0-9])' + x.replace(/[-\s]/g, '[-\\s]?') + '([^a-z0-9]|$)').test(t);
  return t.includes(x);
});

function triagem(v) {
  const t = norm(v.title).replace(/[()\[\]\/|,–—:]/g, ' ');
  if (temTermo(t, SENIORIDADE)) return { ok: false, motivo: 'senioridade' };
  if (/engenhari|engenheir/.test(t) && !/software|computac|dados|sistemas|\bti\b|automacao de|dev/.test(t)) return { ok: false, motivo: 'engenharia' };
  if (temTermo(t, FORA_AREA) || temTermo(t, ENG_NAO_TI)) return { ok: false, motivo: 'fora_area' };
  let tier = null;
  if (/business develop|sales develop/.test(t)) tier = 3;
  else if (temTermo(t, T1)) tier = 1; else if (temTermo(t, T2)) tier = 2; else if (temTermo(t, T3)) tier = 3;
  const entrada = temTermo(t, ENTRADA);
  if (tier === null && !entrada) return { ok: false, motivo: 'sem_termo' };
  if (tier === null) tier = 3;
  return { ok: true, tier, entrada };
}

// ====== EXECUÇÃO ======
const itens = $input.all();
const sd = $getWorkflowStaticData('global');
const producao = $execution.mode === 'production';
let modo = 'diario';
try { modo = $('Montar busca').first().json.modo || 'diario'; } catch (e) { }

const vistos = new Set(Array.isArray(sd.vistos) ? sd.vistos : []);
const ordemVistos = Array.isArray(sd.vistos) ? sd.vistos.slice() : [];
let fila = Array.isArray(sd.fila) ? sd.fila : [];
const marcaVisto = (k) => { if (!vistos.has(k)) { vistos.add(k); ordemVistos.push(k); } };

const stats = { modo, emails: 0, emailsComErro: 0, extraidas: 0, repetidas: 0, descartadas: 0, novasNaFila: 0, enviadasIA: 0, naFila: 0, porFonte: {} };
const hoje = Date.now();

for (const it of itens) {
  const j = it.json || {};
  if (!j.id && !j.text && !j.html) continue; // item vazio (busca sem resultado)
  stats.emails++;
  try {
    const de = (typeof j.from === 'string' ? j.from : (j.from && (j.from.text || (j.from.value && j.from.value[0] && j.from.value[0].address))) || j.From || '').toLowerCase();
    const assunto = j.subject || j.Subject || '';
    const data = j.date || (j.internalDate ? new Date(Number(j.internalDate)).toISOString() : null);
    const texto = j.text || '';
    const html = j.html || '';
    let achadas = [];
    if (de.includes('linkedin')) {
      achadas = parseLinkedIn(/jobs\/view\//.test(texto) ? texto : htmlParaTexto(html), {});
    } else if (de.includes('glassdoor')) {
      achadas = parseGlassdoor(/jobListingId=/.test(texto) ? texto : htmlParaMd(html), {});
    } else if (de.includes('match.indeed')) {
      achadas = parseIndeedMatch(texto.length > 100 ? texto : htmlParaTexto(html), { subject: assunto });
    } else if (de.includes('indeed')) {
      achadas = parseIndeedAlerta(/[?&]jk=/.test(texto) ? texto : htmlParaTexto(html), {});
    }
    for (const v of achadas) {
      stats.extraidas++;
      stats.porFonte[v.source] = (stats.porFonte[v.source] || 0) + 1;
      v.description = (v.description || '').slice(0, SNIPPET_MAX);
      v.emailDate = data;
      v.emailId = j.id;
      v.beneficios = v.beneficios || [];
      v.sig = 'sg:' + hash(norm(v.title).replace(/[^a-z0-9]+/g, ' ').trim() + '|' + norm(v.companyName).replace(/[^a-z0-9]+/g, ' ').trim() + '|' + norm((v.location || '').split(',')[0]).replace(/ e regiao.*$/, '').trim());
      if (vistos.has(v.key) || vistos.has(v.sig)) { stats.repetidas++; continue; }
      marcaVisto(v.key); marcaVisto(v.sig);
      const tr = triagem(v);
      if (!tr.ok) { stats.descartadas++; continue; }
      v.tier = tr.tier; v.entrada = tr.entrada;
      v.enfileiradaEm = hoje;
      fila.push(v);
      stats.novasNaFila++;
    }
  } catch (e) {
    stats.emailsComErro++;
  }
}

// validade da fila
const limite = DIAS_VALIDADE * 86400000;
fila = fila.filter(v => (hoje - (v.enfileiradaEm || hoje)) < limite && ((v.ageDays || 0) + (hoje - (v.enfileiradaEm || hoje)) / 86400000) < DIAS_VALIDADE);

// ordem: tier (dados > TI > outras), nível de entrada primeiro, mais novas primeiro
const chave = (v) => v.tier + (v.entrada ? 0 : 0.5);
fila.sort((a, b) => (chave(a) - chave(b)) || ((a.ageDays ?? 99) - (b.ageDays ?? 99)) || (new Date(b.emailDate || 0) - new Date(a.emailDate || 0)));

const qtd = producao ? LIMITE_IA_POR_RODADA : LIMITE_TESTE;
const hojeLista = fila.slice(0, qtd);
fila = fila.slice(qtd);
if (fila.length > MAX_FILA) fila = fila.slice(0, MAX_FILA);

stats.enviadasIA = hojeLista.length;
stats.naFila = fila.length;
stats.producao = producao;

sd.vistos = ordemVistos.slice(-MAX_VISTOS);
sd.fila = fila;

if (!hojeLista.length) return [{ json: { _vazio: true, _stats: stats } }];
return hojeLista.map((v, i) => ({ json: { ...v, ...(i === 0 ? { _stats: stats } : {}) } }));

