// ===== IDS PARA MARCAR =====
// Lista os emails lidos para o Gmail colocar o rótulo "Vagas-processado".
// Só marca em execução de verdade (agendada/webhook). Em teste manual não marca nada,
// porque a fila de vagas só é gravada de forma permanente fora do teste.
if ($execution.mode !== 'production') return [];
let emails = [];
try { emails = $('Buscar emails').all(); } catch (e) { return []; }
const ids = [...new Set(emails.map(e => e.json && e.json.id).filter(Boolean))];
return ids.map(id => ({ json: { messageId: id } }));

// ===== MONTAR RESUMO =====
// Gera um aviso curto no Telegram: sempre no backfill; no diário só se houver erro de leitura.
const it = $input.first().json || {};
const s = it._stats;
if (!s) return [];
if (s.modo !== 'backfill' && !s.emailsComErro) return [];
const fonte = Object.entries(s.porFonte || {}).map(([k, v]) => `${k.replace(/_/g, ' ')}: ${v}`).join(' · ') || '—';
let t = s.modo === 'backfill' ? '📦 *Backfill de vagas por email*\n' : '⚙️ *Vagas por Email — aviso*\n';
t += `📧 Emails lidos: ${s.emails}\n🔎 Vagas extraídas: ${s.extraidas} (${fonte})\n♻️ Repetidas: ${s.repetidas} · 🗑 Descartadas pelo título: ${s.descartadas}\n`;
t += `🆕 Novas na fila: ${s.novasNaFila}\n🤖 Analisadas agora: ${s.enviadasIA} · ⏳ Ainda na fila: ${s.naFila}`;
if (s.naFila > 0) t += '\n(o que ficou na fila é analisado nas próximas execuções, 50 vagas por vez)';
if (s.emailsComErro) t += `\n⚠️ Emails com erro de leitura: ${s.emailsComErro}`;
if (!s.producao) t += '\n🧪 Execução de teste: nada foi gravado.';
return [{ json: { texto: t } }];

// ===== MONTAR TEXTO DA VAGA =====
// Junta o que veio da página da vaga (HTTP) com o que veio no email.
// Se a página não abriu (login, bloqueio), usa só o trecho do email e avisa a IA.
const DESCRICAO_MAX = 1800;

const job = $('Loop Over Items').item.json;
const resp = $json || {};
const html = typeof resp.html === 'string' ? resp.html : (typeof resp.data === 'string' ? resp.data : '');

const decode = (s) => (s || '').replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(parseInt(n, 10))).replace(/&amp;/g, '&');
const semTags = (s) => decode((s || '')
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
  .replace(/<li[^>]*>/gi, '\n• ').replace(/<br\s*\/?>|<\/(p|div|li|ul|h\d|tr)>/gi, '\n')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t ]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();

let pagina = '', salMin = null, salMax = null, remotoPagina = false;
if (html && html.length > 500 && !/authwall|captcha|are you a human|just a moment|acesso negado|access denied/i.test(html.slice(0, 6000))) {
  // 1) JSON-LD (LinkedIn e outros)
  for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
    try {
      const o = JSON.parse(m[1]);
      const p = [].concat(o, o['@graph'] || []).find(x => x && /JobPosting/i.test(x['@type'] || ''));
      if (p) {
        if (p.description) pagina = semTags(decode(p.description));
        const bs = p.baseSalary && p.baseSalary.value;
        if (bs && (bs.minValue || bs.value)) {
          const mult = /year/i.test(bs.unitText || '') ? 1 / 12 : /hour/i.test(bs.unitText || '') ? 176 : /week/i.test(bs.unitText || '') ? 4.33 : /day/i.test(bs.unitText || '') ? 22 : 1;
          salMin = Math.round(Number(bs.minValue || bs.value) * mult); salMax = Math.round(Number(bs.maxValue || bs.minValue || bs.value) * mult);
        }
        if (/TELECOMMUTE/i.test(p.jobLocationType || '')) remotoPagina = true;
        break;
      }
    } catch (e) { }
  }
  // 2) blocos conhecidos de descrição
  if (pagina.length < 150) {
    const padroes = [
      /<div[^>]*class="[^"]*show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
      /<div[^>]*id="jobDescriptionText"[^>]*>([\s\S]*?)<\/div>\s*<\/div>/i,
      /<div[^>]*data-test="jobDescription[^"]*"[^>]*>([\s\S]*?)<\/div>/i
    ];
    for (const re of padroes) { const m = html.match(re); if (m && semTags(m[1]).length > 150) { pagina = semTags(m[1]); break; } }
  }
  // 3) meta description
  if (pagina.length < 150) {
    const m = html.match(/<meta[^>]*(?:property="og:description"|name="description")[^>]*content="([^"]*)"/i) || html.match(/<meta[^>]*content="([^"]*)"[^>]*(?:property="og:description"|name="description")/i);
    if (m && decode(m[1]).length > 120) pagina = decode(m[1]);
  }
}

// Critérios que o LinkedIn mostra na página (nível de experiência, tipo de emprego, função, setor)
const criterios = [...(html || '').matchAll(/description__job-criteria-text[^>]*>\s*([^<]{2,60}?)\s*</gi)].map(m => decode(m[1]).trim()).filter(Boolean).slice(0, 4);

const emailTxt = (job.description || '').trim();
let textoVaga = '', fonteTexto = 'email';
if (pagina.length >= 150) { textoVaga = pagina; fonteTexto = 'pagina'; }
else { textoVaga = emailTxt; }
textoVaga = textoVaga.slice(0, DESCRICAO_MAX);

const sMin = job.salaryMin || salMin || null, sMax = job.salaryMax || salMax || null;
const infoExtra = [
  `Fonte: ${job.source}${job.rating ? ' (nota da empresa ' + job.rating + ')' : ''}`,
  job.ageDays != null ? `Publicada há ${job.ageDays} dia(s)` : '',
  sMin ? `Salário informado: R$ ${sMin}${sMax && sMax !== sMin ? ' a R$ ' + sMax : ''} por mês` : '',
  (job.beneficios || []).length ? `Benefícios informados: ${job.beneficios.join(', ')}` : '',
  criterios.length ? `Critérios do LinkedIn: ${criterios.join(' | ')}` : '',
  (job.modalidade || remotoPagina) ? `Modalidade informada: ${job.modalidade || 'remoto'}` : '',
  fonteTexto === 'email' ? 'ATENÇÃO: só há o trecho do email (a página da vaga não abriu); a descrição pode estar incompleta.' : ''
].filter(Boolean).join('\n');

return {
  json: {
    ...job,
    salaryMin: sMin, salaryMax: sMax,
    modalidade: job.modalidade || (remotoPagina ? 'remoto' : null),
    textoVaga, fonteTexto, infoExtra,
    descricaoCurta: textoVaga.length < 100 && job.source !== 'indeed_match'
  }
};

// ===== CALCULA SCORE (Code in JavaScript1) =====
// A IA devolve só FATOS sobre a vaga. A nota é calculada aqui, com regras fixas e visíveis.
// Começa em 100 e desconta o que atrapalha. Dois tipos de desconto:
//  - IMPEDITIVO (pleno/sênior, formatura exigida, outra formação, fora de BH...): nenhum bônus compensa.
//  - COMPENSÁVEL (requisito faltando, área fora de TI mas compatível, salário baixo...): bônus (até +30) recuperam pontos.

// ====== CONFIGURAÇÃO ======
const CORTE = 60;                 // nota mínima para ir ao Telegram
const SALARIO_MINIMO = 0;        // AJUSTE: abaixo disso aparece aviso e desconto (0 desliga)
    const ANO_FORMATURA = 2030;      // AJUSTE: ano da sua formatura (vagas que exigem formatura antes são penalizadas)
const BONUS_MAX = 30;
const AREAS_TI = ['dados', 'ia', 'automacao', 'suporte', 'qa', 'dev', 'ti_geral'];
const AREAS_MEIO = ['atendimento', 'comercial', 'logistica', 'administrativo', 'dp_contabil_financeiro'];
const BAIRROS_RMBH = ['contagem', 'betim', 'nova lima', 'sabara', 'santa luzia', 'ribeirao das neves', 'vespasiano', 'lagoa santa', 'ibirite', 'sarzedo', 'esmeraldas'];
const EXPERIENCIAS = {
  planilhas_excel: 'Excel/planilhas', controle_processos: 'controle de processos', atendimento: 'atendimento',
  digitalizacao: 'digitalização de processos', registro_sistemas: 'registro em sistemas', contratos_propostas: 'contratos/propostas'
};
const CVS = {
  Dados: 'Dados e Operações (DV3)', QA: 'QA / Processos / TI Geral (QATV3)', Suporte: 'Suporte / Service Desk (SOV3)',
  Trainee: 'Trainee e Entrada em TI', Ingles: 'English IT Support (Resume)'
};

const norm = (s) => (s || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const limpa = (s) => (s || '').toString().replace(/[*_`\[\]]/g, '').replace(/\s+/g, ' ').trim();
const lista = (v) => (Array.isArray(v) ? v : (v ? [v] : [])).map(limpa).filter(Boolean);
const reais = (n) => 'R$ ' + Math.round(n).toLocaleString('pt-BR');

// 1. Resposta da IA
let raw = ($json.text || '').replace(/```json/gi, '').replace(/```/g, '').trim();
const i0 = raw.indexOf('{'), i1 = raw.lastIndexOf('}');
if (i0 !== -1 && i1 > i0) raw = raw.slice(i0, i1 + 1);
// Se o JSON vier com defeito (aspas soltas, vírgula sobrando), tenta consertar antes de desistir
const tentaParse = (t) => { try { return JSON.parse(t); } catch (e) { return null; } };
function salvar(t) {
  const o = tentaParse(t.replace(/[“”]/g, '"').replace(/,\s*([}\]])/g, '$1'));
  if (o) return o;
  const str = (k) => { const m = t.match(new RegExp('"' + k + '"\\s*:\\s*"([^"]*)"')); return m ? m[1] : ''; };
  const num = (k) => { const m = t.match(new RegExp('"' + k + '"\\s*:\\s*(-?\\d+(?:\\.\\d+)?)')); return m ? Number(m[1]) : null; };
  const bool = (k) => new RegExp('"' + k + '"\\s*:\\s*true').test(t);
  const arr = (k) => { const m = t.match(new RegExp('"' + k + '"\\s*:\\s*\\[([^\\]]*)\\]')); return m ? [...m[1].matchAll(/"([^"]+)"/g)].map(x => x[1]) : []; };
  if (!str('area')) return null;
  const rm = t.match(/"resumo_vaga"\s*:\s*"([\s\S]*?)"\s*}?\s*$/);
  return {
    area: str('area'), nivel: str('nivel'), anos_exigidos: num('anos_exigidos') || 0, formatura_exigida_ate: num('formatura_exigida_ate'),
    curso_exigido_incompativel: bool('curso_exigido_incompativel'), formato: str('formato'), cidade: str('cidade'),
    salario_mensal_min: num('salario_mensal_min'), salario_mensal_max: num('salario_mensal_max'),
    beneficios: arr('beneficios'), requisitos_faltantes: arr('requisitos_faltantes'), requisitos_em_estudo: arr('requisitos_em_estudo'),
    pede_excel: bool('pede_excel'), pede_python_ou_analise_basico: bool('pede_python_ou_analise_basico'),
    aceita_iniciante: bool('aceita_iniciante'), programa_estruturado: bool('programa_estruturado'),
    experiencias_ligadas: arr('experiencias_ligadas'), cv_sugerido: str('cv_sugerido'), pontos_fortes: arr('pontos_fortes'),
    resumo_vaga: rm ? rm[1].replace(/\\"/g, '"') : ''
  };
}
let ai = {}, erroIA = false;
const motivoErro = !raw ? 'resposta vazia da IA (possível limite do Groq)' : 'resposta da IA fora do formato';
ai = salvar(raw);
if (!ai) { ai = {}; erroIA = true; }

// 2. Dados da vaga (já com o que veio do email/página)
const job = $('Montar texto').item.json;

// 3. Pontuação
const ded = [], bon = [];
const D = (v, m, duro) => ded.push([v, m, !!duro]);
const B = (v, m) => bon.push([v, m]);
const avisos = [];

const area = norm(ai.area);
const nivel = norm(ai.nivel);
const anos = Number(ai.anos_exigidos) || 0;
const emEstudo = lista(ai.requisitos_em_estudo);
// um mesmo item não pode contar como "falta" e "em estudo" ao mesmo tempo
const faltantes = lista(ai.requisitos_faltantes).filter(f => !emEstudo.some(e => norm(e).includes(norm(f)) || norm(f).includes(norm(e))));
// sem descrição, a IA não tem base para afirmar requisitos nem experiências: ignora
const temDescricao = !job.descricaoCurta;

if (!erroIA) {
  // Área: as áreas que ele quer NÃO perdem ponto
  if (AREAS_MEIO.includes(area)) D(20, 'área fora de TI, mas compatível');
  else if (area === 'engenharia_nao_ti') D(60, 'engenharia fora de software', true);
  else if (area === 'outra_formacao') D(70, 'exige formação de outra área', true);
  else if (!AREAS_TI.includes(area)) D(45, 'área fora do perfil', true);

  // Nível / experiência
  if (['pleno', 'senior', 'lideranca'].includes(nivel) || anos >= 3) D(50, 'pede pleno/sênior ou 3+ anos', true);
  else if (anos >= 1) D(10, `pede ${anos} ano(s) de experiência`);

  // Elegibilidade
  const form = Number(ai.formatura_exigida_ate);
  if (isFinite(form) && form > 0 && form < ANO_FORMATURA) D(45, `exige formatura até ${form} (sua previsão: ${ANO_FORMATURA})`, true);
  if (ai.curso_exigido_incompativel === true) D(40, 'exige curso superior de outra área', true);

  // Requisitos técnicos
  if (faltantes.length && temDescricao) D(Math.min(faltantes.length, 5) * 4, `${faltantes.length} requisito(s) que faltam`);
  if (emEstudo.length && temDescricao) D(Math.min(emEstudo.length, 4) * 2, `${emEstudo.length} requisito(s) em estudo`);
}

// Modalidade e local (por regras, não pela IA)
const locTxt = norm(job.location) || norm(ai.cidade);
const modEmail = job.modalidade || null;
const modIA = norm(ai.formato);
let modalidade = modEmail || (['remoto', 'hibrido', 'presencial'].includes(modIA) ? modIA : null);
if (/remot|home office|trabalho a distancia/.test(locTxt)) modalidade = 'remoto';
if (modalidade !== 'remoto' && locTxt.trim()) {
  if (/belo horizonte|\bbh\b/.test(locTxt)) { /* ok */ }
  else if (BAIRROS_RMBH.some(c => locTxt.includes(c))) D(6, 'região metropolitana de BH');
  else if (/^(brasil|brazil)$/.test(locTxt.trim())) { /* local genérico: não penaliza */ }
  else if (/\b(mg|minas gerais)\b/.test(locTxt)) D(45, 'presencial/híbrido em outra cidade de MG', true);
  else D(45, 'fora de BH e não é remoto', true);
}

// Descrição
if (job.descricaoCurta) D(10, 'sem descrição suficiente (nota limitada)', true);

// Salário
const num = (x) => { const n = Number(x); return isFinite(n) && n >= 500 && n <= 100000 ? n : null; };
const sMin = num(job.salaryMin) || num(ai.salario_mensal_min);
const sMax = num(job.salaryMax) || num(ai.salario_mensal_max) || sMin;
const sRef = sMin ? (sMin + (sMax || sMin)) / 2 : null;
if (sMin !== null) {
  if (sMin < SALARIO_MINIMO) { D(10, `salário abaixo de ${reais(SALARIO_MINIMO)}`, true); avisos.push(`⚠️ Abaixo do mínimo: ${reais(sMin)}`); }
  else if (sMin < 3500) D(4, 'salário de 2.500 a 3.499', true);
}

// Bônus
if (!erroIA) {
  if (modalidade === 'remoto') B(10, 'home office');
  else if (modalidade === 'hibrido') B(3, 'híbrido');
  if (sRef !== null) {
    if (sRef >= 12000) B(16, 'salário ≥ 12 mil');
    else if (sRef >= 6000) B(14, 'salário de 6 a 12 mil');
    else if (sRef >= 5000) B(8, 'salário de 5 a 6 mil');
    else if (sRef >= 3500) B(5, 'salário ≥ 3,5 mil');
  }
  const todosBen = [...lista(job.beneficios), ...lista(ai.beneficios)];
  const benUnicos = [];
  for (const b of todosBen) { const k = norm(b); if (/vale.?transporte|^vt$/.test(k)) continue; if (!benUnicos.some(x => norm(x) === k)) benUnicos.push(b); }
  if (benUnicos.length) B(Math.min(benUnicos.length, 4) * 2, `${Math.min(benUnicos.length, 4)} benefício(s)`);
  const exps = temDescricao ? lista(ai.experiencias_ligadas).map(norm).filter(k => EXPERIENCIAS[k]) : [];
  const expsUn = [...new Set(exps)];
  if (expsUn.length) B(Math.min(expsUn.length, 3) * 3, 'experiência que você já tem: ' + expsUn.slice(0, 3).map(k => EXPERIENCIAS[k]).join(', '));
  if (temDescricao && ai.pede_excel === true) B(4, 'pede Excel');
  if (temDescricao && ai.pede_python_ou_analise_basico === true) B(3, 'Python/análise básico');
  if (temDescricao && ai.aceita_iniciante === true) B(4, 'aceita iniciante');
  if (temDescricao && ai.programa_estruturado === true) B(4, 'programa estruturado');
  if (job.rating && job.rating >= 4.0) B(3, `empresa nota ${job.rating}`);
  if (job.ageDays != null && job.ageDays <= 3) B(3, 'vaga recente');
}

const dedDuro = ded.filter(x => x[2]).reduce((a, x) => a + x[0], 0);
const dedMole = ded.filter(x => !x[2]).reduce((a, x) => a + x[0], 0);
const totalBon = Math.min(bon.reduce((a, x) => a + x[0], 0), BONUS_MAX);
const bonusUsado = Math.min(totalBon, dedMole);   // bônus só recupera descontos compensáveis
const score = erroIA ? 0 : Math.max(0, Math.min(100, Math.round(100 - dedDuro - dedMole + bonusUsado)));
const aprovada = erroIA ? true : score >= CORTE;   // se a IA falhar, avisa para você conferir
const forte = !erroIA && dedDuro === 0 && score >= 85 && AREAS_TI.includes(area) && ((sRef !== null && sRef >= 6000) || (sRef !== null && sRef >= 3500 && modalidade === 'remoto'));

if (erroIA) avisos.push(`⚠️ A IA não conseguiu analisar esta vaga (${motivoErro}) — avalie você mesmo.`);

// 4. Textos para o Telegram
const fonteNome = { linkedin: '🔎 LinkedIn', glassdoor: '📧 Glassdoor', indeed: '📧 Indeed', indeed_match: '📧 Indeed (sugestão)' }[job.source] || job.source;
const idade = job.ageDays == null ? '' : (job.ageDays === 0 ? ' · publicada hoje' : ` · há ${job.ageDays} dia(s)`);
let modTxt = { remoto: 'Remoto', hibrido: 'Híbrido', presencial: 'Presencial' }[modalidade] || '';
if (modTxt && norm(job.location).includes(norm(modTxt))) modTxt = '';   // evita "Remoto · Remoto"
const salTxt = sMin ? (sMax && sMax !== sMin ? `${reais(sMin)} a ${reais(sMax)}` : reais(sMin)) : 'não informado';
const bens = [...new Set([...lista(job.beneficios), ...lista(ai.beneficios)].map(norm))].length
  ? [...lista(job.beneficios), ...lista(ai.beneficios)].filter((b, i, a) => a.findIndex(x => norm(x) === norm(b)) === i).slice(0, 6).join(', ') : '';
const ajustes = [...ded.map(x => `−${x[0]} ${x[1]}`), ...bon.map(x => `+${x[0]} ${x[1]}`)].join(' | ') + (bon.length && dedMole ? ` (bônus aproveitado: +${bonusUsado})` : '');
const cv = CVS[ai.cv_sugerido] || CVS[Object.keys(CVS).find(k => norm(k) === norm(ai.cv_sugerido))] || '';
const pf = lista(ai.pontos_fortes).slice(0, 4);
const rf = faltantes.slice(0, 5);
const estudoMostrar = temDescricao ? emEstudo : [];
const resumo = limpa(ai.resumo_vaga) || (erroIA ? 'Não foi possível analisar automaticamente.' : '');

let cab = `🎯 *NOVA VAGA COMPATÍVEL!*${forte ? ' 🔥 *MATCH FORTE*' : ''}\n`;
cab += `📌 *Vaga:* ${limpa(job.title) || 'Título não informado'}\n`;
cab += `🏢 *Empresa:* ${limpa(job.companyName) || 'Empresa não informada'}\n`;
cab += `📍 *Local:* ${limpa(job.location)}${modTxt ? ' · ' + modTxt : ''}\n`;
cab += `💰 *Salário:* ${salTxt}\n`;
if (bens) cab += `🎁 *Benefícios:* ${limpa(bens)}\n`;
cab += `📊 *Score de Aderência:* ${erroIA ? 'n/d' : score + '/100'}\n`;
if (cv) cab += `📄 *CV sugerido:* ${cv}\n`;
cab += `${fonteNome}${idade}\n`;
if (avisos.length) cab += '\n' + avisos.join('\n') + '\n';
if (resumo) cab += `\n💡 *Resumo:* _${resumo}_\n`;
if (pf.length) cab += `\n✅ *Pontos Fortes:*\n• ${pf.join('\n• ')}\n`;
if (rf.length && temDescricao) cab += `\n⚠️ *Requisitos faltantes:*\n• ${rf.join('\n• ')}\n`;
if (estudoMostrar.length) cab += `\n📚 *Você está estudando:* ${estudoMostrar.slice(0, 4).join(', ')}\n`;
if (ajustes && !erroIA) cab += `\n📐 _Ajustes: ${ajustes.slice(0, 320)}_\n`;
if (job.fonteTexto === 'email') cab += `\nℹ️ _A página da vaga não abriu; análise feita com o trecho do email._\n`;

return {
  json: {
    jobId: job.rawId || job.key || '',
    title: limpa(job.title), company: limpa(job.companyName), location: limpa(job.location),
    url: (job.link || '').replace(/\)/g, '%29'),
    score, aprovada, erroIA, forte,
    pontos_fortes: pf, requisitos_faltantes: rf, resumo_vaga: resumo,
    ajustes, cabecalho: cab
  }
};

