// ===== REMETENTES NOVOS =====
// Avisa quando aparece, na caixa de entrada, um remetente de vaga/candidatura que o workflow não conhece.
const CONHECIDOS = ['linkedin.com', 'glassdoor.com', 'indeed.com', 'gupy.io', 'gupy.com.br', 'inhire.app', 'solides.com', 'solides.com.br', 'mindsight.com.br', 'vagas.com.br', 'google.com', 'gmail.com', 'accounts.google.com'];
const MAX_AVISADOS = 300;

const sd = $getWorkflowStaticData('global');
const avisados = new Set(Array.isArray(sd.remetentesAvisados) ? sd.remetentesAvisados : []);
const achados = new Map();
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.id) continue;
  const bruto = typeof j.from === 'string' ? j.from : (j.from && (j.from.text || (j.from.value && j.from.value[0] && j.from.value[0].address))) || j.From || '';
  const m = String(bruto).toLowerCase().match(/[a-z0-9._%+-]+@([a-z0-9.-]+\.[a-z]{2,})/);
  if (!m) continue;
  const base = m[1];
  if (CONHECIDOS.some(c => base === c || base.endsWith('.' + c))) continue;
  if (avisados.has(base)) continue;
  if (!achados.has(base)) achados.set(base, (j.subject || j.Subject || '').toString().slice(0, 80));
}
if (!achados.size) return [];
const linhas = [...achados.entries()].slice(0, 12).map(([d, s]) => `• ${d.replace(/[*_`\[\]]/g, '')} — ${s.replace(/[*_`\[\]]/g, '')}`);
if ($execution.mode === 'production') {
  for (const d of achados.keys()) avisados.add(d);
  sd.remetentesAvisados = [...avisados].slice(-MAX_AVISADOS);
}
return [{ json: { texto: `📬 *Remetentes novos de vaga/candidatura*\nEncontrei emails de remetentes que o workflow ainda não lê:\n${linhas.join('\n')}\n\nSe algum for alerta de vagas, avise para incluir na busca.` } }];
